WITH cleaned AS (SELECT *, MONTH(order_date) AS order_date_month FROM orders WHERE order_date >= DATE '2023-07-17' AND channel IS NOT DISTINCT FROM 'web') SELECT *, AVG(order_date_month) OVER (PARTITION BY status ORDER BY order_date_month, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS order_date_month_avg_6_prior, ROW_NUMBER() OVER (ORDER BY shipping_fee, id) AS event_seq, NTILE(5) OVER w_hist AS discount_bucket FROM cleaned WINDOW w_hist AS (PARTITION BY channel ORDER BY discount, id);
